import fs from 'node:fs';
import path from 'node:path';
import { checkAnchorLine, anchorStatementDigest } from '../src/index';

// Conformance: the SDK gives the verdict recorded in docs/protocol/vectors/audit-anchor.json (family audit-anchor) for every line.
// The vectors are generated by scripts/protocol/gen-audit-vectors.js and re-derived by the Node and Python independent verifiers.
const file = path.join(__dirname, '..', '..', '..', 'docs', 'protocol', 'vectors', 'audit-anchor.json');
const vectors = JSON.parse(fs.readFileSync(file, 'utf8')) as {
  cases: Array<{ id: string; description: string; input: { line: string }; expected?: { digest: string }; expectedError?: { code: string } }>;
};

describe('anchor line conformance vectors (AUDIT-ANCHOR-*)', () => {
  it('has the pinned minimum of cases', () => { expect(vectors.cases.length).toBeGreaterThanOrEqual(20); });
  it.each(vectors.cases.map((c) => [c.id, c.description, c] as const))('%s %s', (_id, _d, c) => {
    const got = checkAnchorLine(c.input.line);
    if (c.expectedError) expect(got).toEqual({ ok: false, code: c.expectedError.code });
    else {
      expect(got.ok).toBe(true);
      if (got.ok) { expect(got.digest).toBe(c.expected?.digest); expect(anchorStatementDigest(got.statement)).toBe(c.expected?.digest); }
    }
  });
});
